{
  "name": "opencode-telegram",
  "version": "0.3.0",
  "description": "OpenCode plugin for Telegram notifications - get notified when tasks complete, respond to permission requests via Telegram",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "type": "module",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "tsc",
    "typecheck": "tsc --noEmit",
    "clean": "rm -rf dist",
    "prepublishOnly": "npm run clean && npm run build"
  },
  "keywords": [
    "opencode",
    "plugin",
    "telegram",
    "notification"
  ],
  "author": "lifening",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/lifening/opencode-telegram"
  },
  "homepage": "https://github.com/lifening/opencode-telegram#readme",
  "dependencies": {
    "@opencode-ai/plugin": "^1.1.65",
    "@opencode-ai/sdk": "^1.1.65"
  },
  "devDependencies": {
    "@types/node": "^22.13.9",
    "typescript": "^5.8.2"
  }
}
